"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["6744"],{63653(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.conferencia_endereco_geo.geo_indisponivel","status":503,"titulo":"O Geo n\xe3o respondeu \u2014 o envio \xe9 recusado, mas o rascunho continua salv\xe1vel"},"descricao":{"codigo":"uniplus.selecao.conferencia_endereco_geo.geo_indisponivel","requisitos":["UNI-REQ-0214","UNI-REQ-0407"],"oQueAconteceu":["O sistema confere no Geo, o cadastro de localidades do Uni+, os\\nmunic\xedpios e os endere\xe7os informados, e n\xe3o aceita um munic\xedpio ou um\\nendere\xe7o sem essa confer\xeancia. O Geo n\xe3o respondeu. Este aviso \xe9\\ntempor\xe1rio e n\xe3o aponta erro nos dados informados.","O que vale depende de onde a confer\xeancia foi pedida:","- **Envio da inscri\xe7\xe3o:** o envio foi recusado por inteiro e nada desta\\n  tentativa foi gravado. No primeiro envio, a inscri\xe7\xe3o n\xe3o foi enviada, e o\\n  que fica \xe9 a \xfaltima vers\xe3o salva do rascunho; se voc\xea alterou respostas\\n  depois do \xfaltimo salvamento e as mandou junto com o pedido de envio,\\n  essas altera\xe7\xf5es n\xe3o foram gravadas. Na corre\xe7\xe3o de inscri\xe7\xe3o j\xe1\\n  enviada, a corre\xe7\xe3o n\xe3o foi gravada, e a inscri\xe7\xe3o e o comprovante do\\n  envio anterior continuam valendo. Este aviso s\xf3 \xe9 dado quando n\xe3o h\xe1\\n  nenhuma outra recusa que o candidato possa corrigir: se houvesse, o\\n  envio seria recusado com 422 e a lista dessas recusas.\\n- **Publica\xe7\xe3o e retifica\xe7\xe3o do processo seletivo:** a confer\xeancia dos\\n  munic\xedpios de prova n\xe3o foi feita, e nada foi gravado.\\n- **Salvamento e importa\xe7\xe3o do rascunho da configura\xe7\xe3o do processo:** o\\n  rascunho \xe9 salvo. O aviso vem uma s\xf3 vez, no campo dos munic\xedpios de\\n  prova (`/provaPresencial/municipios`), no lugar de um aviso por\\n  munic\xedpio, e nenhum munic\xedpio fica aprovado por falta de confer\xeancia.\\n  No painel de conformidade, o item da prova presencial fica pendente."],"comoResolver":["Aguarde alguns minutos e tente de novo. Se for o primeiro envio de\\ninscri\xe7\xe3o, abra o rascunho e confira as respostas que voc\xea alterou desde o\\n\xfaltimo salvamento, refazendo as que faltarem. Se for a corre\xe7\xe3o de uma\\ninscri\xe7\xe3o j\xe1 enviada, refa\xe7a a corre\xe7\xe3o a partir da inscri\xe7\xe3o como ela\\nest\xe1. Em seguida, envie outra vez. Se o prazo de inscri\xe7\xe3o estiver perto\\ndo fim, tente de novo o quanto antes.","Na configura\xe7\xe3o do processo seletivo, salve o rascunho outra vez ou\\ntente publicar de novo quando o Geo voltar: a confer\xeancia dos munic\xedpios\\nde prova se repete a cada salvamento e na publica\xe7\xe3o. Se o aviso\\npersistir por muito tempo, procure o canal de suporte do processo\\nseletivo."],"ondeAparece":["Envio da inscri\xe7\xe3o do candidato","Publica\xe7\xe3o e retifica\xe7\xe3o do processo seletivo","Salvamento e importa\xe7\xe3o do rascunho da configura\xe7\xe3o do processo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Conferencia endereco geo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);